#include <iostream>

int main() {
    try {
        try {
            throw 3.14;               // double
        } catch (int) {              // 只匹配 int，不匹配 double
            std::cout << "int\n";
        }
        // double 未被内层捕获，向上传播
    } catch (...) {                 // 外层兜底
        std::cout << "caught unknown in outer\n";
    }
}
